style.css:
@-moz-document domain("youtube.com") {
/* Background - Soft Pink */
    body {
        background: url('https://i.imgur.com/your-kawaii-bg.png') no-repeat center center fixed;
        background-size: cover;
    }

    /* Change main background color */
    ytd-app {
        background: #ffe6f2 !important;
    }

    /* Header Bar */
    #masthead-container {
        background: linear-gradient(90deg, #ffb6c1, #ff69b4) !important;
    }

    /* Video Titles - Cute Font & Pink */
    .ytd-video-renderer .title, .ytd-grid-video-renderer .title {
        font-family: 'Comic Sans MS', cursive !important;
        color: #ff4da6 !important;
    }

    /* Sidebar Background */
    #guide-content {
        background: #ffccdd !important;
        border-radius: 10px;
    }

    /* Buttons - Kawaii Look */
    ytd-button-renderer {
        background: #ff99cc !important;
        border-radius: 20px !important;
        padding: 5px 10px !important;
    }

    /* Like & Subscribe Buttons */
    .ytd-toggle-button-renderer, .ytd-subscribe-button-renderer {
        background: #ff66b2 !important;
        color: white !important;
        border-radius: 15px !important;
    }
    
    /* Add sparkles effect */
    body::after {
        content: '';
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        pointer-events: none;
        background: url('https://i.imgur.com/your-sparkles.png') repeat;
        opacity: 0.3;
    }
}
